WITH filtered_transactions AS (SELECT * FROM transactions WHERE (txn_time >= '2024-03-21' AND merchant IN ('Amazon', '7-Eleven')) OR txn_type = 'DEBIT'), transactions_stats AS (SELECT merchant, ROUND(STDDEV(amount), 2) AS stddev_amount, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(merchant))) AS merchant_values FROM filtered_transactions GROUP BY merchant) SELECT * FROM transactions_stats ORDER BY stddev_amount DESC, merchant
